import { describe, it, expect } from 'vitest';
import { validateLimit, LimitExceededError } from '../src/transfers/limitPolicy';

describe('Premium transfer limit — post-patch', () => {
  it('allows $50 000 (previously at ceiling)', () => {
    expect(() => validateLimit('premium', 50_000)).not.toThrow();
  });
  it('allows $99 999 (below new ceiling)', () => {
    expect(() => validateLimit('premium', 99_999)).not.toThrow();
  });
  it('allows exactly $100 000 (new ceiling)', () => {
    expect(() => validateLimit('premium', 100_000)).not.toThrow();
  });
  it('rejects $100 001 (above new ceiling)', () => {
    expect(() => validateLimit('premium', 100_001)).toThrow(LimitExceededError);
  });
  it('standard tier: still rejects $10 001', () => {
    expect(() => validateLimit('standard', 10_001)).toThrow(LimitExceededError);
  });
});
